css:
/* 夸张极简主义 · Exaggerated Minimalism
   不是更少元素，而是把标题、数字、按钮放大到不合比例，靠留白和发丝线分隔。
   颜色只有纸白、墨黑和一个信号红；所有面板取消阴影，只留 1px 细线。 */

html[data-theme] {
  color-scheme: light;
  --bg: #fafaf7;
  --ink: #0b0b0c; --muted: #5f5f66; --dim: #8b8b92;
  --soft: #26262b; --meta: #5f5f66; --bright: #000000;
  --line: #deddd6; --line2: #eceae2;
  --accent: #ff3b2f; --accent2: #0b0b0c; --accentText: #ffffff;
  --good: #1f8a5b; --warn: #b26a00;
  --glow1: transparent; --glow2: transparent;
  --panel: #ffffff; --panel2: #fafaf7;
  --dock1: #ffffff; --dock2: #ffffff;
  --glass: rgba(255, 255, 255, 0.9);
  --track: #eceae2; --scroll: #c9c8c0; --coverbg: #efeee9;
  --menu: #ffffff; --menu1: #ffffff; --menu2: #fafaf7; --chev: #8b8b92;
  --edge: #deddd6; --edge2: #ff3b2f;
  --hover: #f3f2ec; --tick: #deddd6;
  --inset: transparent; --wordactive: #000000; --swborder: #0b0b0c;
  --shadow-dock: 0 24px 60px -40px rgba(0, 0, 0, 0.28);
  --serif: "Helvetica Neue", "Segoe UI Variable Display", "PingFang SC", system-ui, sans-serif;
  --bottom: 132px;
  --shell-nav: #fafaf7; --shell-nav2: #fafaf7;
  --shell-navin: #0b0b0c; --shell-navmuted: #6d6d74; --shell-navline: #e3e2db;
}

html[data-theme] body {
  background: #fafaf7;
  color: #0b0b0c;
}
html[data-theme] body::before, html[data-theme] body::after { content: none; }

/* 侧栏：只剩字与线 */
html[data-theme] .sidebar {
  margin: 0; padding: 28px 18px 24px; background: #fafaf7;
  border-right: 1px solid #e3e2db; border-radius: 0; box-shadow: none;
}
html[data-theme] .brand { padding: 0 6px 28px; border-bottom: 1px solid #e3e2db; margin-bottom: 18px; }
html[data-theme] .brand .brand-name, html[data-theme] .brand strong {
  font-size: 15px; font-weight: 800; letter-spacing: 0.22em; text-transform: uppercase;
}
html[data-theme] .nav button {
  padding: 11px 6px; border: 0; border-radius: 0; font-size: 10.5px; font-weight: 600;
  letter-spacing: 0.16em; text-transform: uppercase; color: #6d6d74;
}
html[data-theme] .nav button:hover { background: transparent; color: #0b0b0c; }
html[data-theme] .nav button.active {
  background: transparent; color: #0b0b0c; font-weight: 800;
  box-shadow: inset 2px 0 0 #ff3b2f; padding-left: 12px;
}

/* 顶栏：没有底板，只有一条发丝线 */
html[data-theme] .topbar {
  margin-top: 0; height: 76px; padding: 0 6px; border-bottom: 1px solid #e3e2db;
  background: rgba(250, 250, 247, 0.92); backdrop-filter: blur(16px);
}
html[data-theme] .search-global { border: 0; border-bottom: 1px solid #deddd6; border-radius: 0; background: transparent; }
html[data-theme] .icon-btn { border: 0; border-radius: 0; background: transparent; }
html[data-theme] .icon-btn:hover { background: #f1f0ea; }

/* 首页：一句话占掉半屏 */
html[data-theme] .ledger-home { max-width: 1180px; }
html[data-theme] .ledger-mast {
  margin-top: 40px; padding: 40px 8px 44px; border: 0; border-bottom: 1px solid #deddd6;
  border-radius: 0; background: transparent; box-shadow: none;
}
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-family: var(--serif); font-size: clamp(64px, 9vw, 128px); line-height: 0.92;
  font-weight: 800; letter-spacing: -0.055em; color: #0b0b0c;
}
html[data-theme] .ledger-mast p, html[data-theme] .subtitle {
  margin-top: 22px; max-width: 34ch; font-size: 15px; line-height: 1.5; color: #6d6d74;
}

/* 卡片：无框、无阴影，靠间距 */
html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 1px solid #eceae2; border-radius: 2px; background: #ffffff;
  box-shadow: none; backdrop-filter: none; -webkit-backdrop-filter: none;
}
html[data-theme] .card { padding: 30px 28px; }
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover { border-color: #0b0b0c; transform: none; }
html[data-theme] .btn {
  border: 1px solid #0b0b0c; border-radius: 999px; background: transparent; color: #0b0b0c;
  font-size: 11px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; padding: 9px 18px;
}
html[data-theme] .btn.primary { background: #0b0b0c; color: #ffffff; }

/* 统计：数字当主角 */
html[data-theme] #page-stats .page-head { padding: 40px 8px 30px; margin-bottom: 24px; border-bottom: 1px solid #deddd6; }
html[data-theme] #page-stats .page-head h1 {
  font-size: clamp(44px, 7vw, 92px); line-height: 0.95; font-weight: 800; letter-spacing: -0.05em;
  background: none; -webkit-text-fill-color: #0b0b0c; color: #0b0b0c;
}
html[data-theme] #page-stats .eyebrow { color: #ff3b2f; letter-spacing: 0.34em; }
html[data-theme] #page-stats .subtitle { max-width: 44ch; color: #6d6d74; font-size: 13px; }
html[data-theme] #page-stats .stat {
  border: 0; border-top: 1px solid #0b0b0c; border-radius: 0; background: transparent;
  box-shadow: none; backdrop-filter: none; padding: 18px 4px 14px;
}
html[data-theme] #page-stats .stat:before { content: none; }
html[data-theme] #page-stats .stat label { font-size: 9px; letter-spacing: 0.28em; color: #8b8b92; }
html[data-theme] #page-stats .stat strong {
  margin: 12px 0 2px; font-family: var(--serif); font-size: clamp(40px, 5vw, 68px);
  font-weight: 300; letter-spacing: -0.05em; color: #0b0b0c;
  background: none; -webkit-text-fill-color: #0b0b0c;
}
html[data-theme] #page-stats .stat em { color: #8b8b92; font-size: 10px; letter-spacing: 0.04em; }
html[data-theme] #page-stats .card { border: 0; border-top: 1px solid #deddd6; border-radius: 0; background: transparent; padding: 22px 4px; }
html[data-theme] #page-stats .section-title { border-bottom: 0; font-size: 15px; font-weight: 700; letter-spacing: -0.01em; }
html[data-theme] #page-stats .section-title small { color: #8b8b92; font-weight: 400; }
html[data-theme] #page-stats .stat-bar {
  padding: 12px 0; margin: 0; border-bottom: 1px solid #eceae2; border-radius: 0; background: transparent;
}
html[data-theme] #page-stats .stat-bar:hover { background: transparent; }
html[data-theme] #page-stats .stat-bar-head span { font-size: 12.5px; color: #26262b; }
html[data-theme] #page-stats .stat-bar-head b { font: 10px/1 var(--mono); color: #8b8b92; }
html[data-theme] #page-stats .stat-track { height: 2px; border-radius: 0; background: #eceae2; box-shadow: none; }
html[data-theme] #page-stats .stat-track i { border-radius: 0; background: #ff3b2f; box-shadow: none; }
html[data-theme] #page-stats .stats-year-head {
  margin-top: 40px; padding: 30px 8px 22px; border: 0; border-top: 1px solid #0b0b0c; border-radius: 0;
  background: transparent; box-shadow: none;
}
html[data-theme] #page-stats .year-title {
  font-size: clamp(40px, 6vw, 80px); font-weight: 800; letter-spacing: -0.05em; margin: 8px 0 10px;
  background: none; -webkit-text-fill-color: #0b0b0c; color: #0b0b0c;
}
html[data-theme] #page-stats #echoYear {
  border: 1px solid #0b0b0c; border-radius: 999px; background: transparent; color: #0b0b0c;
  font-size: 11px; font-weight: 700; letter-spacing: 0.1em; padding: 9px 16px;
}
html[data-theme] #page-stats #echoBody { padding: 22px 4px; }

/* 设置 */
html[data-theme] .ct-box { border: 1px solid #eceae2; border-radius: 2px; background: #ffffff; box-shadow: none; }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid #deddd6; border-radius: 2px; background: #fafaf7; color: #0b0b0c;
}
html[data-theme] .setting-row { border-bottom: 1px solid #eceae2; }

/* 播放条：细胶囊，只有一个黑点 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 20px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 14px 26px; border: 1px solid #deddd6; border-radius: 999px;
    background: #ffffff; box-shadow: 0 30px 70px -50px rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px);
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn {
  border-radius: 50%; background: #0b0b0c; color: #ffffff; box-shadow: none;
}
html[data-theme] .mini-player { border: 1px solid #deddd6; border-radius: 999px; background: #ffffff; box-shadow: none; }

html[data-theme] .cue { border-bottom: 1px solid #eceae2; }
html[data-theme] .cue.active { box-shadow: inset 2px 0 0 #ff3b2f; }
html[data-theme] .word.active, html[data-theme] .cue.active .word { color: #0b0b0c; background: #ffe9e7; box-shadow: none; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: #fafaf7; color: #0b0b0c; }
html[data-theme] .wp-bg { filter: blur(44px) saturate(60%) brightness(1.5) contrast(.9); opacity: .26; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(250,250,247,.95) 0%, rgba(250,250,247,.86) 52%, rgba(250,250,247,.7) 78%, rgba(250,250,247,.95) 100%); }
html[data-theme] .wp-kicker { color: #ff3b2f; font-weight:700;letter-spacing:.26em; }
html[data-theme] .wp-title { color: #0b0b0c; font-weight:800;letter-spacing:-.05em; }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(11,11,12,.6); }
html[data-theme] .wp-cue.active::before { background: #ff3b2f; box-shadow: none; width:clamp(4px,.3vw,5px);border-radius:0; }
html[data-theme] .wp-cue.active .wp-en { color: #0b0b0c; text-shadow: none; font-weight:800;letter-spacing:-.05em; }
html[data-theme] .wp-word.past { color: #0b0b0c; }
html[data-theme] .wp-word.active { color: #0b0b0c; background-image: linear-gradient(180deg, transparent 64%, rgba(255,59,47,.3) 64%, rgba(255,59,47,.3) 94%, transparent 94%); text-shadow: none; border-radius:0; }
html[data-theme] .wp-zh { color: rgba(11,11,12,.55); font-weight:400; }
html[data-theme] .wp-label { color: rgba(11,11,12,.35); }
html[data-theme] .wpbtn { background: #ffffff; border-color: #deddd6; color: #0b0b0c; border-radius:4px;box-shadow:none;font-weight:600;letter-spacing:.02em; }
html[data-theme] .wpbtn:hover { background: #ff3b2f; border-color: #ff3b2f; color: #ffffff; }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .docksheet { border-radius: 0; border: 2px solid #0b0b0c; background: #fafaf7; box-shadow: none; }
html[data-theme] .dshead { border-bottom: 2px solid #0b0b0c; }
html[data-theme] .dstile { background: #fff; border: 2px solid #0b0b0c; border-radius: 0; color: #0b0b0c; font-weight: 600; letter-spacing: -.01em; box-shadow: none; }
html[data-theme] .dstile:hover { background: #0b0b0c; color: #fafaf7; border-color: #0b0b0c; }
html[data-theme] .dstile:hover svg { stroke: #fafaf7; }
html[data-theme] .dstile[aria-pressed="true"], html[data-theme] .dstile[aria-expanded="true"] { background: #ff3b2f; color: #fff; border-color: #ff3b2f; }
html[data-theme] .dspill { border-radius: 0; border: 2px solid #0b0b0c; background: #fff; color: #0b0b0c; font-weight: 600; }
html[data-theme] .dsmute { border-radius: 0; border: 2px solid #0b0b0c; }
html[data-theme] .dsrange::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 22px; border-radius: 0; background: #ff3b2f; }
